implementation:
#include <linux/uaccess.h>
#include <linux/sctp.h>

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_assoc_stats stats = {0};
    struct sctp_association *asoc;
    int assoc_id;
    int ret = 0;

    /* Check if the provided length is sufficient for the association ID. */
    if (len < sizeof(assoc_id))
        return -EINVAL;

    /* Copy the association ID from user space. */
    if (copy_from_user(&assoc_id, optval, sizeof(assoc_id)))
        return -EFAULT;

    /* Retrieve the association based on the ID. */
    asoc = sctp_id2assoc(sk, assoc_id);
    if (!asoc)
        return -ENOENT;

    /* Populate the statistics structure with various metrics. */
    stats.assoc_id = assoc_id;
    stats.cumu_flight = asoc->c.sack.cumu_flight;
    stats.rto = asoc->rto;
    stats.max_rto = asoc->rto_max;
    stats.min_rto = asoc->rto_min;

    /* Update the maximum observed RTO. */
    if (asoc->rto > stats.max_rto)
        stats.max_rto = asoc->rto;

    /* Prepare the statistics for return to the user. */
    if (copy_to_user(optval, &stats, sizeof(stats))) {
        ret = -EFAULT;
    } else {
        if (put_user(sizeof(stats), optlen))
            ret = -EFAULT;
    }

    return ret;
}
